import 'package:flutter/material.dart';
import '../widgets/shared.dart';
const cities=['تهران','مشهد','رشت','شیراز','تبریز','کرمانشاه','اهواز','اصفهان'];
const levels=['کم‌مواد','روزمره','مجلسی'];
class SettingsScreen extends StatefulWidget {final String city,level;final bool localFirst;final Future<void> Function(String,String,bool) onSave;const SettingsScreen({super.key,required this.city,required this.level,required this.localFirst,required this.onSave});@override State<SettingsScreen> createState()=>_SettingsScreenState();}
class _SettingsScreenState extends State<SettingsScreen>{late String city,level;late bool local;@override void initState(){super.initState();city=widget.city;level=widget.level;local=widget.localFirst;}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const SectionTitle('شهر شما'),DropdownButtonFormField<String>(value:city,items:[for(final x in cities)DropdownMenuItem(value:x,child:Text(x))],onChanged:(v)=>setState(()=>city=v??city)),const SectionTitle('ترجیح غذایی'),for(final x in levels)Card(child:RadioListTile<String>(value:x,groupValue:level,title:Text(x=='کم‌مواد'?'کم‌مواد و اقتصادی':x=='روزمره'?'غذای روزمره':'مجلسی و رستورانی'),onChanged:(v)=>setState(()=>level=v??level))),SwitchListTile(title:const Text('غذاهای محلی شهرم را بیشتر نشان بده'),value:local,onChanged:(v)=>setState(()=>local=v)),PrimaryButton(text:'ذخیره تنظیمات',onPressed:()async{await widget.onSave(city,level,local);if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('تنظیمات ذخیره شد')));})]);}
